package com.lrsmotors.app
import android.content.*
import android.telephony.TelephonyManager
class CallReceiver:BroadcastReceiver(){override fun onReceive(c:Context,i:Intent){if(i.action!=TelephonyManager.ACTION_PHONE_STATE_CHANGED)return;val state=i.getStringExtra(TelephonyManager.EXTRA_STATE)?:return;val pref=c.getSharedPreferences("call_state",Context.MODE_PRIVATE);when(state){TelephonyManager.EXTRA_STATE_RINGING,TelephonyManager.EXTRA_STATE_OFFHOOK->pref.edit().putBoolean("active",true).apply();TelephonyManager.EXTRA_STATE_IDLE->if(pref.getBoolean("active",false)){pref.edit().putBoolean("active",false).apply();android.os.Handler(android.os.Looper.getMainLooper()).postDelayed({val resolved=SimCallResolver.latestForSelectedSim(c)?:return@postDelayed;val p=resolved.phone;val pending=pref.getString("pending_followup_call","").orEmpty();if(pending.isNotBlank()&&LeadStore.normalize(pending)==LeadStore.normalize(p)){LeadStore(c).setAction(p,"DONE");pref.edit().remove("pending_followup_call").apply()}else{c.startActivity(Intent(c,MainActivity::class.java).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP).putExtra("after_call_phone",p))}},1500)}}}}